using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

namespace GameHoverDetails
{
    internal sealed class HoverSvgPath
    {
        public HoverSvgPath(string data, double opacity, bool stroke)
        {
            Data = data;
            Opacity = opacity;
            Stroke = stroke;
        }

        public string Data { get; }
        public double Opacity { get; }
        public bool Stroke { get; }
    }

    internal sealed class HoverSvgIcon
    {
        public HoverSvgIcon(IReadOnlyList<HoverSvgPath> paths, bool pixelSnap = false)
        {
            Paths = paths;
            PixelSnap = pixelSnap;
        }

        public IReadOnlyList<HoverSvgPath> Paths { get; }
        public bool PixelSnap { get; }

        public FrameworkElement CreateVisual(double sizeDip, Brush brush)
        {
            var canvas = new Canvas
            {
                Width = 24,
                Height = 24,
                SnapsToDevicePixels = PixelSnap
            };
            if (PixelSnap)
            {
                RenderOptions.SetEdgeMode(canvas, EdgeMode.Aliased);
            }

            foreach (var spec in Paths)
            {
                Geometry geo;
                try
                {
                    geo = Geometry.Parse(spec.Data);
                }
                catch
                {
                    continue;
                }

                var path = new Path
                {
                    Data = geo,
                    Opacity = spec.Opacity,
                    IsHitTestVisible = false
                };

                if (spec.Stroke)
                {
                    path.Fill = Brushes.Transparent;
                    path.Stroke = brush;
                    path.StrokeThickness = 2;
                    path.StrokeStartLineCap = PenLineCap.Round;
                    path.StrokeEndLineCap = PenLineCap.Round;
                    path.StrokeLineJoin = PenLineJoin.Round;
                }
                else
                {
                    path.Fill = brush;
                    path.Stroke = null;
                }

                canvas.Children.Add(path);
            }

            var box = new Viewbox
            {
                Width = sizeDip,
                Height = sizeDip,
                Stretch = Stretch.Uniform,
                Child = canvas,
                IsHitTestVisible = false
            };
            if (PixelSnap)
            {
                RenderOptions.SetBitmapScalingMode(box, BitmapScalingMode.NearestNeighbor);
                RenderOptions.SetEdgeMode(box, EdgeMode.Aliased);
            }

            return box;
        }
    }

